import heapq


def topo(deps: dict[str, list[str]]) -> list[str]:
    nodes = set(deps.keys())
    for prereqs in deps.values():
        nodes.update(prereqs)

    indegree = {node: 0 for node in nodes}
    dependents = {node: [] for node in nodes}
    for task, prereqs in deps.items():
        for pre in set(prereqs):
            indegree[task] += 1
            dependents[pre].append(task)

    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for nxt in dependents[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(order) != len(nodes):
        raise ValueError("cycle")
    return order
